import tseslint from "typescript-eslint";

// ESLint is kept for a single rule with no Biome equivalent:
// no-restricted-imports enforces the apps/src import boundary.
// Formatting and file-level linting are owned by Biome (biome.json).
export default tseslint.config(
  {
    ignores: [
      "node_modules/**",
      "public/**",
      "apps/web/public/**",
      "apps/web/dist/**",
      "apps/web/.astro/**",
      "apps/frontend/dist/**",
      // Generated by TanStack Router; it ships its own eslint-disable header.
      "apps/frontend/src/routeTree.gen.ts",
      ".opencode/**",
      ".omc/**",
      ".agents/**",
      ".codex/**",
      ".playwright-mcp/**",
      "dist/**",
      "scripts/**",
      ".wrangler/**",
      "**/.wrangler/**",
      ".astro/**",
      "**/.astro/**",
      "**/__probe.test.ts",
    ],
  },
  // Cross-app imports are allowed only for SSR assertions inside tests;
  // src/ of any app must never import another app's files.
  {
    files: ["apps/*/src/**/*.{ts,tsx}"],
    languageOptions: { parser: tseslint.parser },
    rules: {
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              group: ["../../../*", "../../../../*", "../../../../../*"],
              message: "No cross-app imports in src/ — shared types live in @shiba/shared.",
            },
          ],
        },
      ],
    },
  },
  // The founder reads module is a single public import boundary.
  {
    files: ["apps/backend/src/**/*.{ts,tsx}"],
    ignores: ["apps/backend/src/founder/reads/**/*"],
    languageOptions: { parser: tseslint.parser },
    rules: {
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            // Repeated here: a later no-restricted-imports entry replaces the cross-app one above.
            {
              group: ["../../../*", "../../../../*", "../../../../../*"],
              message: "No cross-app imports in src/ — shared types live in @shiba/shared.",
            },
            {
              regex: "^(?!.*(?:^|/)reads/index(?:\\.js)?$).*(?:^|/)reads/.*$",
              message: "Import founder read-grant APIs from founder/reads/index.js, not engine internals.",
            },
          ],
        },
      ],
      // no-restricted-imports only sees static imports; this repo lazy-loads routes with import().
      "no-restricted-syntax": [
        "error",
        {
          selector: "ImportExpression[source.value=/(^|\\/)reads\\/(?!index(\\.js)?$)/]",
          message: "Import founder read-grant APIs from founder/reads/index.js, not engine internals.",
        },
      ],
    },
  },
  // packages/* are the leaf layer: they must never reach into apps/.
  {
    files: ["packages/*/src/**/*.{ts,tsx}", "packages/*/test/**/*.{ts,tsx}"],
    // The SDK contract test drives the real v1 handler so the published client
    // and the Worker cannot drift; it is the one sanctioned test-only exception.
    ignores: ["packages/sdk/test/contract.test.ts"],
    languageOptions: { parser: tseslint.parser },
    rules: {
      "no-restricted-imports": [
        "error",
        {
          patterns: [
            {
              group: ["../../apps/**", "../../../apps/**", "*/apps/*/**"],
              message: "Packages must not import apps/ — shared contracts live in @shiba/shared.",
            },
            {
              regex: "^\\.\\./\\.\\./[^/]+/src(?:/|$)",
              message: "Import a workspace package by its name (@shiba/...), not its source path.",
            },
          ],
        },
      ],
    },
  },
);
